solution.python:
qator = input()

natija = []
for c in qator:
    if 'a' <= c <= 'z':
        c = chr(ord(c) - 32)
    elif 'A' <= c <= 'Z':
        c = chr(ord(c) + 32)
    natija.append(c)

print("".join(natija))

